SELECT EXISTS (SELECT 1 FROM user_block b WHERE b.blocker_id = :recipient AND b.blocked_id = :actor) OR EXISTS (SELECT 1 FROM user_mute m WHERE m.user_id = :recipient AND m.muted_user_id = :actor AND m.hide_notifications AND (m.expires_at IS NULL OR m.expires_at > :now))
SELECT EXISTS (SELECT 1 FROM user_domain_block d JOIN federation_remote_actor a ON a.domain = d.domain WHERE d.user_id = :recipient AND a.id = :remote) OR EXISTS (SELECT 1 FROM federation_remote_actor sa WHERE sa.id = :remote AND EXISTS (SELECT 1 FROM (SELECT sa.domain AS domain UNION ALL SELECT SUBSTRING_INDEX(sa.domain, '.', -6) UNION ALL SELECT SUBSTRING_INDEX(sa.domain, '.', -5) UNION ALL SELECT SUBSTRING_INDEX(sa.domain, '.', -4) UNION ALL SELECT SUBSTRING_INDEX(sa.domain, '.', -3) UNION ALL SELECT SUBSTRING_INDEX(sa.domain, '.', -2)) cp JOIN federation_domain_block cb ON cb.domain = cp.domain WHERE cb.severity = 'SUSPEND')) OR EXISTS (SELECT 1 FROM federation_remote_actor la WHERE la.id = :remote AND EXISTS (SELECT 1 FROM (SELECT la.domain AS domain UNION ALL SELECT SUBSTRING_INDEX(la.domain, '.', -6) UNION ALL SELECT SUBSTRING_INDEX(la.domain, '.', -5) UNION ALL SELECT SUBSTRING_INDEX(la.domain, '.', -4) UNION ALL SELECT SUBSTRING_INDEX(la.domain, '.', -3) UNION ALL SELECT SUBSTRING_INDEX(la.domain, '.', -2)) cp JOIN federation_domain_block cb ON cb.domain = cp.domain WHERE cb.severity = 'LIMIT') AND NOT EXISTS (SELECT 1 FROM federation_following lf WHERE lf.user_id = :recipient AND lf.remote_actor_id = la.id AND lf.accepted_at IS NOT NULL)) OR (EXISTS (SELECT 1 FROM federation_remote_block hrb WHERE hrb.user_id = :recipient AND hrb.remote_actor_id = :remote) OR EXISTS (SELECT 1 FROM federation_remote_mute hrn WHERE hrn.user_id = :recipient AND hrn.remote_actor_id = :remote AND hrn.hide_notifications AND (hrn.expires_at IS NULL OR hrn.expires_at > :now)))
SELECT EXISTS (SELECT 1 FROM user_block b WHERE b.blocker_id = :recipient AND b.blocked_id = :actor) OR EXISTS (SELECT 1 FROM user_mute m WHERE m.user_id = :recipient AND m.muted_user_id = :actor AND m.hide_notifications AND (m.expires_at IS NULL OR m.expires_at > :now)) OR EXISTS (SELECT 1 FROM note_conversation_mute c WHERE c.user_id = :recipient AND c.conversation_id = :conversation)
